    background-position: left center, left center !important;
    background-size: 0% 100%, 100% 100%; 

    -webkit-mask-image: linear-gradient(to right,
        #000 0%, #000 23.5%,
        transparent 23.5%, transparent 25.5%,
        #000 25.5%, #000 49%,
        transparent 49%, transparent 51%,
        #000 51%, #000 74.5%,
        transparent 74.5%, transparent 76.5%,
        #000 76.5%, #000 100%
    ) !important;
    mask-image: linear-gradient(to right,
        #000 0%, #000 23.5%,
        transparent 23.5%, transparent 25.5%,
        #000 25.5%, #000 49%,
        transparent 49%, transparent 51%,
        #000 51%, #000 74.5%,
        transparent 74.5%, transparent 76.5%,
        #000 76.5%, #000 100%
    ) !important;

    animation: xtStoryProgress 15s linear infinite !important;
}

@keyframes xtStoryProgress {
    0% { background-size: 0% 100%, 100% 100%; }
    100% { background-size: 100% 100%, 100% 100%; }
}
@-webkit-keyframes xtStoryProgress {
    0% { background-size: 0% 100%, 100% 100%; }
    100% { background-size: 100% 100%, 100% 100%; }
}

/* ================= 2. 顶部用户信息 (Node 1) ================= */
.xt-text:nth-of-type(1) {
    position: absolute !important;
    top: 35px !important; left: 65px !important;
    color: #ffffff !important; 
    font-size: 15px !important; font-weight: 600 !important;
    z-index: 10 !important;
    text-shadow: 0 1px 4px rgba(0,0,0,0.5) !important;
}
.xt-text:nth-of-type(1)::before {
